import {characters,missions,practice} from './metodologias-ageis-dados.js';

const mode=document.body.dataset.mode;
const playerKey='portal-teste-ageis-player-v1',simulationKey='portal-teste-ageis-simulado-v1';
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageAvailable=true;
function read(key){try{return JSON.parse(localStorage.getItem(key))}catch{storageAvailable=false;return null}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{storageAvailable=false}showStorageWarning()}
function showStorageWarning(){if(!storageAvailable){$('storageWarning').hidden=false;$('storageWarning').textContent='O navegador não permitiu salvar o progresso. Você pode estudar normalmente nesta página, mas o progresso poderá ser perdido ao sair.'}}
const raw=read(playerKey)||{};
let player={character:characters.some(c=>c.id===raw.character)?raw.character:'maya',done:Array.isArray(raw.done)?[...new Set(raw.done.filter(id=>missions.some(m=>m.id===id)))]:[],current:missions.some(m=>m.id===raw.current)?raw.current:missions[0].id,bestScore:Number.isInteger(raw.bestScore)&&raw.bestScore>=0&&raw.bestScore<=practice.length?raw.bestScore:0};
function character(){return characters.find(c=>c.id===player.character)}
function savePlayer(){const c=character();write(playerKey,{...player,avatar:c.icon,avatarName:c.name+' · '+c.role})}
function renderPlayer(){const c=character();$('playerPanel').innerHTML=`<div class="head-row"><div class="player"><span class="player-icon" aria-hidden="true">${c.icon}</span><div><strong>${esc(c.name)} · ${esc(c.role)}</strong><span class="small">${esc(c.description)}</span></div></div><button class="btn secondary" data-picker>Trocar personagem</button></div><div class="rewards" style="margin-top:15px"><span class="pill">⭐ ${player.done.length*100} XP na trilha</span><span class="pill">🏅 ${player.done.length} de 8 conquistas</span><span class="pill">🏆 Melhor simulado: ${player.bestScore} / 40</span></div>`;renderCharacters()}
function renderCharacters(){$('characters').innerHTML=characters.map(c=>`<button class="character ${c.id===player.character?'selected':''}" data-character="${c.id}" aria-pressed="${c.id===player.character}"><span class="portrait" aria-hidden="true">${c.icon}</span><strong>${esc(c.name)}</strong><span class="role">${esc(c.role)}</span><p>${esc(c.description)}</p></button>`).join('')}

let gateAnswer=null;
function renderTrail(){renderPlayer();$('trailProgress').innerHTML=`<div class="progress" role="progressbar" aria-label="Missões concluídas" aria-valuemin="0" aria-valuemax="8" aria-valuenow="${player.done.length}"><i style="width:${player.done.length/8*100}%"></i></div><span class="small">${player.done.length} de 8 missões concluídas</span>`;$('missionMap').innerHTML=missions.map((m,i)=>`<button class="mission-node ${player.current===m.id?'current':''} ${player.done.includes(m.id)?'done':''}" data-mission="${m.id}" ${player.current===m.id?'aria-current="step"':''}><span class="symbol" aria-hidden="true">${m.icon}</span><span><small>Missão ${i+1}${player.done.includes(m.id)?' · concluída ✓':''}</small><strong>${esc(m.title)}</strong></span></button>`).join('');renderLesson();$('trailFinish').hidden=player.done.length!==missions.length;if(player.done.length===missions.length)$('trailFinish').innerHTML='<h2>🏆 Guilda preparada para a próxima etapa!</h2><p>Você concluiu as 8 missões. Agora pratique os 40 conceitos em novas situações e use as explicações para fortalecer o que ainda precisa revisar.</p><div class="actions"><a class="btn" href="metodologias-ageis-simulado.html">Entrar no simulado</a><a class="btn secondary" href="metodologias-ageis.html">Ir para a prova com código</a></div>'}
function renderLesson(){const m=missions.find(m=>m.id===player.current),i=missions.indexOf(m),done=player.done.includes(m.id),gate=m.gate,answered=gateAnswer!==null,correct=gateAnswer===gate.c;$('lesson').innerHTML=`<div class="chapter-label">${esc(m.world)} · missão ${i+1} de 8</div><h2 style="margin-top:9px">${m.icon} ${esc(m.title)}</h2><p class="muted">${esc(m.intro)}</p><div class="concepts">${m.concepts.map(([title,definition,example])=>`<article class="concept"><h3>${esc(title)}</h3><p>${esc(definition)}</p><div class="example"><strong>NO JOGO DA EQUIPE</strong>${esc(example)}</div></article>`).join('')}</div>${m.id==='kanban'?'<div class="kanban" aria-label="Exemplo de quadro Kanban"><div><strong>A fazer</strong><span>Criar inventário</span></div><div><strong>Em andamento</strong><span>Testar salvamento</span></div><div><strong>Concluído</strong><span>Tela inicial verificada</span></div></div>':''}<div class="checkpoint"><div class="chapter-label">Checkpoint da missão</div><h3 style="margin-top:10px">${esc(gate.q)}</h3>${gate.o.map((o,j)=>`<button class="option ${answered&&j===gate.c?'correct':''} ${answered&&j===gateAnswer&&!correct?'wrong':''}" data-gate="${j}" ${answered?'disabled':''}>${String.fromCharCode(65+j)}. ${esc(o)}</button>`).join('')}${answered?`<div class="feedback ${correct?'':'wrong'}" role="status"><strong>${correct?'✓ Missão concluída!':'Vamos revisar a decisão.'}</strong><br>${esc(gate.why)}</div>${!correct?'<div class="actions"><button class="btn secondary" data-retry-gate>Tentar novamente</button></div>':''}`:''}${done&&!answered?'<p class="small">✓ Esta missão já está concluída. Você pode rever o desafio quando quiser.</p>':''}</div><div class="actions">${i>0?`<button class="btn secondary" data-mission="${missions[i-1].id}">← Missão anterior</button>`:''}${i<missions.length-1?`<button class="btn" data-mission="${missions[i+1].id}">Próxima missão →</button>`:'<a class="btn" href="metodologias-ageis-simulado.html">Praticar no simulado →</a>'}<a class="btn secondary" href="./">Sair da trilha</a></div><div class="sources">Referências para estudar: <a href="https://agilemanifesto.org/iso/ptbr/manifesto.html" target="_blank" rel="noopener">Manifesto Ágil</a><a href="https://scrumguides.org/scrum-guide.html" target="_blank" rel="noopener">Scrum Guide</a><a href="https://kanbanguides.org/the-kanban-guide/2025.5/" target="_blank" rel="noopener">Kanban Guide</a></div>`}

export function validCampaign(s){return !!s&&Array.isArray(s.order)&&s.order.length===practice.length&&new Set(s.order).size===practice.length&&s.order.every(i=>Number.isInteger(i)&&i>=0&&i<practice.length)&&Array.isArray(s.answers)&&s.answers.length===practice.length&&s.answers.every(a=>a===null||Number.isInteger(a)&&a>=0&&a<4)&&Number.isInteger(s.cursor)&&s.cursor>=0&&s.cursor<practice.length&&typeof s.finished==='boolean'}
let campaign=null,running=false;
if(mode==='simulation'){const saved=read(simulationKey);if(validCampaign(saved))campaign=saved}
function saveCampaign(){if(campaign)write(simulationKey,campaign)}
function newCampaign(){const order=practice.map((_,i)=>i);for(let i=order.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[order[i],order[j]]=[order[j],order[i]]}campaign={order,answers:Array(practice.length).fill(null),cursor:0,finished:false};saveCampaign()}
function simulationScore(){return campaign.answers.reduce((n,a,i)=>n+(a===practice[campaign.order[i]].correct?1:0),0)}
function renderSimulation(){renderPlayer();$('simulationIntro').hidden=running;$('simulationMap').hidden=!running;$('quiz').hidden=!running||campaign?.finished;$('simulationResult').hidden=!running||!campaign?.finished;if(!running){$('beginSimulation').textContent=campaign?.finished?'Ver meu resultado':campaign?'Retomar campanha →':'Começar campanha →';return}const answered=campaign.answers.filter(a=>a!==null).length;$('simulationCount').textContent=`${answered} de 40 respondidos`;$('simulationBar').style.width=answered/practice.length*100+'%';$('questionMap').innerHTML=campaign.order.map((_,i)=>`<button class="question-node ${i===campaign.cursor?'current':''} ${campaign.answers[i]!==null?'done':''}" data-question="${i}" aria-label="Desafio ${i+1}${campaign.answers[i]!==null?', respondido':''}">${i+1}</button>`).join('');if(campaign.finished){renderResult();return}const q=practice[campaign.order[campaign.cursor]],m=missions.find(m=>m.id===q.mission),choice=campaign.answers[campaign.cursor],hasAnswer=choice!==null,correct=choice===q.correct;$('quiz').innerHTML=`<div class="head-row"><span class="chapter-label">Desafio ${campaign.cursor+1} de 40</span><span class="pill">${m.icon} ${esc(m.world)}</span></div><p class="small" style="margin-top:9px">${esc(m.title)}</p><h2 class="quiz-title">${esc(q.text)}</h2>${q.options.map((o,i)=>`<button class="option ${hasAnswer&&i===q.correct?'correct':''} ${hasAnswer&&i===choice&&!correct?'wrong':''}" data-answer="${i}" ${hasAnswer?'disabled':''}>${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}${hasAnswer?`<div class="feedback ${correct?'':'wrong'}" role="status"><strong>${correct?'✓ Boa decisão! +20 XP':'Vamos fortalecer este conceito.'}</strong><br>${esc(q.explain)}</div>`:''}<div class="actions">${hasAnswer?`<button class="btn" data-next>${campaign.cursor===practice.length-1?'Concluir campanha →':'Próximo desafio →'}</button>`:''}<a class="btn secondary" href="metodologias-ageis-trilha.html?missao=${m.id}">Revisar este assunto</a><a class="btn secondary" href="./">Sair do simulado</a></div><p class="small" style="margin-top:15px">${storageAvailable?'Progresso salvo neste navegador. Você pode sair e retomar a campanha.':'O progresso não está sendo salvo neste navegador.'}</p>`}
function renderResult(){const score=simulationScore(),rank=score>=36?'S':score>=32?'A':score>=28?'B':score>=24?'C':'D';$('simulationResult').innerHTML=`<div class="head-row"><div><div class="chapter-label">Campanha concluída</div><h2 style="margin-top:8px">Sua guilda ganhou experiência</h2></div><span class="rank">RANK ${rank}</span></div><div class="score">${score} / 40</div><p class="muted">${score>=32?'Você demonstrou boa compreensão dos conceitos. Continue revisando para explicar suas decisões com segurança.':'Use as explicações e as missões abaixo para revisar os conceitos e tentar novamente.'}</p><div class="rewards"><span class="pill">⭐ ${score*20} XP no treino</span><span class="pill">💎 ${score*5} cristais de aprendizado</span></div><h3 style="margin-top:23px">Revisão por missão</h3><div class="review-grid">${missions.map(m=>{const entries=campaign.order.map((q,i)=>({q:practice[q],a:campaign.answers[i]})).filter(e=>e.q.mission===m.id),hits=entries.filter(e=>e.a===e.q.correct).length;return `<a class="review-link" href="metodologias-ageis-trilha.html?missao=${m.id}"><strong>${m.icon} ${esc(m.title)}</strong><br><span>${hits} de ${entries.length} acertos · revisar missão</span></a>`}).join('')}</div><div class="actions"><button class="btn secondary" data-restart>Jogar novamente</button><a class="btn" href="metodologias-ageis.html">Ir para a prova com código →</a><a class="btn secondary" href="./">Voltar ao portal</a></div><p class="small" style="margin-top:15px">A pontuação é apenas de estudo. A nota oficial é calculada na prova e registrada no painel do professor.</p>`}

document.addEventListener('click',event=>{const t=event.target.closest('button');if(!t)return;
  if(t.hasAttribute('data-picker')){$('characterPicker').hidden=!$('characterPicker').hidden;return}
  if(t.dataset.character){if(!characters.some(c=>c.id===t.dataset.character))return;player.character=t.dataset.character;savePlayer();renderPlayer();$('characterPicker').hidden=true;return}
  if(mode==='trail'){
    if(t.dataset.mission){if(!missions.some(m=>m.id===t.dataset.mission))return;player.current=t.dataset.mission;gateAnswer=null;savePlayer();renderTrail();$('lesson').scrollIntoView({block:'start'});return}
    if(t.hasAttribute('data-gate')){if(gateAnswer!==null)return;const m=missions.find(m=>m.id===player.current),value=Number(t.dataset.gate);if(!Number.isInteger(value)||value<0||value>=m.gate.o.length)return;gateAnswer=value;if(value===m.gate.c&&!player.done.includes(m.id)){player.done.push(m.id);savePlayer()}renderTrail();return}
    if(t.hasAttribute('data-retry-gate')){gateAnswer=null;renderLesson();return}
  }
  if(mode==='simulation'){
    if(t.hasAttribute('data-start')){if(!campaign)newCampaign();running=true;renderSimulation();(campaign.finished?$('simulationResult'):$('quiz')).scrollIntoView({block:'start'});return}
    if(t.hasAttribute('data-answer')){if(!campaign||campaign.answers[campaign.cursor]!==null)return;const choice=Number(t.dataset.answer);if(!Number.isInteger(choice)||choice<0||choice>3)return;campaign.answers[campaign.cursor]=choice;saveCampaign();renderSimulation();return}
    if(t.hasAttribute('data-next')){if(!campaign||campaign.answers[campaign.cursor]===null)return;if(campaign.cursor===practice.length-1){const missed=campaign.answers.indexOf(null);if(missed===-1){campaign.finished=true;player.bestScore=Math.max(player.bestScore,simulationScore());savePlayer()}else campaign.cursor=missed}else campaign.cursor++;saveCampaign();renderSimulation();(campaign.finished?$('simulationResult'):$('quiz')).scrollIntoView({block:'start'});return}
    if(t.hasAttribute('data-question')){const i=Number(t.dataset.question);if(!campaign||!Number.isInteger(i)||i<0||i>=practice.length)return;campaign.cursor=i;campaign.finished=false;saveCampaign();renderSimulation();$('quiz').scrollIntoView({block:'start'});return}
    if(t.hasAttribute('data-restart')&&confirm('Começar uma nova campanha? O resultado anterior continua como recorde, mas as respostas desta campanha serão reiniciadas.')){newCampaign();running=true;renderSimulation();$('quiz').scrollIntoView({block:'start'});return}
  }
});
if(mode==='trail'){const requested=new URLSearchParams(location.search).get('missao');if(missions.some(m=>m.id===requested))player.current=requested;renderTrail()}else renderSimulation();
if(!raw.character)$('characterPicker').hidden=false;
showStorageWarning();
